// Font loading function: DedicationFont
static Font LoadFont_DedicationFont(void)
{
    Font font = { 0 };

    font.baseSize = 30;
    font.glyphCount = 120;
    font.glyphPadding = 4;

    // Custom font loading
    // NOTE: Compressed font image data (DEFLATE), it requires DecompressData() function
    int fontDataSize_DedicationFont = 0;
    unsigned char *data = DecompressData(fontData_DedicationFont, COMPRESSED_DATA_SIZE_FONT_DEDICATIONFONT, &fontDataSize_DedicationFont);
    Image imFont = { data, 512, 256, 1, 2 };

    // Load texture from image
    font.texture = LoadTextureFromImage(imFont);
    UnloadImage(imFont);  // Uncompressed data can be unloaded from memory

    // Assign glyph recs and info data directly
    // WARNING: This font data must not be unloaded
    font.recs = (Rectangle *)fontRecs_DedicationFont;
    font.glyphs = (GlyphInfo *)fontGlyphs_DedicationFont;

    return font;
}
